import{_ as d,o as e,a,b as p}from"./app.BGziXukh.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"技术附录","link":"/guide/technical_appendix/technical_appendix"},{"text":"C++标准支持","link":"/guide/technical_appendix/cpp_standard_support/cpp_standard_support"},{"text":"Device侧C++语言支持","link":"/guide/technical_appendix/cpp_standard_support/cpp_language_feature/cpp_language_feature"},{"text":"C++14语言特性","link":"/guide/technical_appendix/cpp_standard_support/cpp_language_feature/cpp14_language_feature"}]},"headers":[],"relativePath":"guide/technical_appendix/cpp_standard_support/cpp_language_feature/cpp14_language_feature.md","filePath":"guide/technical_appendix/cpp_standard_support/cpp_language_feature/cpp14_language_feature.md","lastUpdated":1795071543000}'),r={name:"guide/technical_appendix/cpp_standard_support/cpp_language_feature/cpp14_language_feature.md"};function s(c,t,n,o,_,g){return e(),a("div",null,[...t[0]||(t[0]=[p('<div><article class="markdown-body"><h1>C++14语言特性</h1><p>Ascend C Device侧对C++14语言特性的支持情况如下表所示：</p><table><thead><tr><th>C++14特性</th><th>C++14 Proposal</th><th>是否支持</th><th>说明</th></tr></thead><tbody><tr><td>上下文转换调整</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2012/n3323.pdf">N3323</a></td><td>是</td><td>if等上下文中explicit bool转换可直接使用。</td></tr><tr><td>二进制字面量</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2012/n3472.pdf">N3472</a></td><td>是</td><td>支持0b、0B两种前缀。</td></tr><tr><td>返回类型推导函数</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2013/n3638.html">N3638</a></td><td>是</td><td>无尾置返回类型的函数可用auto推导返回类型。</td></tr><tr><td>广义lambda捕获、初始化捕获</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2013/n3648.html">N3648</a></td><td>是</td><td><code>[sum = expr]</code>形式可用。SIMD与SIMT混合编程场景写法详见<a href="./lambda_expressions.html">Lambda表达式</a>。</td></tr><tr><td>泛型lambda表达式</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2013/n3649.html">N3649</a></td><td>是</td><td>SIMD与SIMT混合编程场景写法详见<a href="./lambda_expressions.html">Lambda表达式</a>。</td></tr><tr><td>变量模板</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2013/n3651.pdf">N3651</a></td><td>是</td><td>支持<code>template &lt;typename T&gt; constexpr T var = ...;</code>变量模板。</td></tr><tr><td>constexpr函数增强</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2013/n3652.html">N3652</a></td><td>是</td><td>constexpr函数内允许局部变量、循环、多返回路径。</td></tr><tr><td>成员初始化器与聚合</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2013/n3653.html">N3653</a></td><td>是</td><td>含默认成员初始化器的类可作为聚合用花括号初始化。</td></tr><tr><td>内存分配澄清</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2013/n3664.html">N3664</a></td><td>否</td><td>Device侧不支持动态内存分配。</td></tr><tr><td>带尺寸的释放</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2013/n3778.html">N3778</a></td><td>否</td><td>Device侧不支持动态内存释放。</td></tr><tr><td><code>[[deprecated]]</code>属性</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2013/n3760.html">N3760</a></td><td>是</td><td>标注弃用后，使用该实体会产生编译告警。</td></tr><tr><td>单引号数字分隔符</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2013/n3781.pdf">N3781</a></td><td>是</td><td><code>1&#39;000&#39;000</code>形式可用。</td></tr></tbody></table></article></div>',1)])])}const i=d(r,[["render",s]]);export{l as __pageData,i as default};
